t.script:
(function () {
    var video = document.getElementById('scan-video');
    var status = document.getElementById('scan-status');
    var form = document.getElementById('scan-form');
    var payload = document.getElementById('scan-payload');
    var sent = false;

    function submit(text) {
        text = (text || '').trim();
        if (sent || text.indexOf('TRP:') !== 0) {
            return;
        }
        sent = true;
        payload.value = text;
        status.textContent = 'Lecture en cours…';
        if (video.srcObject) {
            video.srcObject.getTracks().forEach(function (track) { track.stop(); });
        }
        form.submit();
    }

    payload.focus();
    payload.addEventListener('keydown', function (event) {
        if (event.key === 'Enter') {
            event.preventDefault();
            submit(payload.value);
        }
    });

    if (!navigator.mediaDevices || !window.isSecureContext) {
        status.textContent = 'La caméra ne s’ouvre qu’en https:// ou sur localhost. Le champ accepte une douchette.';
        return;
    }

    function watch(useDetector) {
        var canvas = document.createElement('canvas');
        var context = canvas.getContext('2d', { willReadFrequently: true });
        var detector = useDetector ? new BarcodeDetector({ formats: ['qr_code'] }) : null;

        function later() {
            if (!sent) {
                setTimeout(tick, 200);
            }
        }

        function tick() {
            if (sent || video.readyState < 2) {
                later();
                return;
            }
            if (detector) {
                detector.detect(video).then(function (codes) {
                    if (codes.length && codes[0].rawValue) {
                        submit(codes[0].rawValue);
                    } else {
                        later();
                    }
                }).catch(function () {
                    detector = null;
                    later();
                });
                return;
            }
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            context.drawImage(video, 0, 0, canvas.width, canvas.height);
            var image = context.getImageData(0, 0, canvas.width, canvas.height);
            var code = window.jsQR(image.data, image.width, image.height, { inversionAttempts: 'dontInvert' });
            if (code && code.data) {
                submit(code.data);
            } else {
                later();
            }
        }

        tick();
    }

    navigator.mediaDevices.getUserMedia({
        video: { facingMode: { ideal: 'environment' } },
        audio: false
    }).then(function (stream) {
        video.srcObject = stream;
        return video.play();
    }).then(function () {
        status.textContent = 'Caméra ouverte. Présentez le QR.';
        watch(typeof BarcodeDetector === 'function');
    }).catch(function () {
        status.textContent = 'Caméra refusée. Autorisez-la dans le navigateur, ou saisissez le QR dans le champ.';
    });
})();
